/* cppi::47c413900f36a3bc0cbe3e6fd5ca04fbbf0ac9693d613f296b0f649011caa642 */
SELECT cppib_sec_id, rating_value FROM performance.cppib_security_rating
                WHERE business_date = '2025-06-03' AND rating_agency = 'CPPIB'

/* cppi::ddbb448a024317d345b3a3f53657c6563ea670b04adeb87f1a23b8c23b54843b */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-24' and end_date = '2025-04-24')
and start_date = '2025-04-24' and end_date = '2025-04-24'

